function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'TodoList' || !Array.isArray(args[0]) || args[0].length !== 0) return 'Start with TodoList() and no arguments.';
  const word = (s, max) => typeof s === 'string' && s.length >= 1 && s.length <= max && /^[A-Za-z0-9]+$/.test(s);
  const id = (v) => Number.isInteger(v) && v >= 1 && v <= 100;
  const counts = { addTask: 0, getAllTasks: 0, getTasksForTag: 0, completeTask: 0 };
  const dueDates = new Set();
  for (let i = 1; i < operations.length; i++) {
    const op = operations[i];
    const a = args[i];
    if (!Object.hasOwn(counts, op)) return 'Only addTask, getAllTasks, getTasksForTag and completeTask can follow the constructor.';
    if (++counts[op] > 100) return 'At most 100 calls to each method.';
    if (!Array.isArray(a)) return 'Each call needs an argument list.';
    if (!id(a[0])) return 'userId is a whole number from 1 to 100.';
    if (op === 'addTask') {
      if (a.length !== 4) return 'addTask takes userId, taskDescription, dueDate and tags.';
      if (!word(a[1], 50)) return 'taskDescription has 1 to 50 letters or digits.';
      if (!id(a[2])) return 'dueDate is a whole number from 1 to 100.';
      if (dueDates.has(a[2])) return 'Every dueDate must be different.';
      dueDates.add(a[2]);
      if (!Array.isArray(a[3]) || a[3].length > 100) return 'tags is a list of at most 100 tags.';
      if (!a[3].every(tag => word(tag, 20))) return 'Each tag has 1 to 20 letters or digits.';
    } else if (op === 'getAllTasks') {
      if (a.length !== 1) return 'getAllTasks takes only userId.';
    } else if (op === 'getTasksForTag') {
      if (a.length !== 2 || !word(a[1], 20)) return 'getTasksForTag takes userId and a tag of 1 to 20 letters or digits.';
    } else {
      if (a.length !== 2 || !id(a[1])) return 'completeTask takes userId and a taskId from 1 to 100.';
    }
  }
  return null;
}

