class TodoList {
  constructor() {
    this.nextId = 1;
    this.taskById = new Map();
    this.tasksByUser = new Map();
  }

  addTask(userId, taskDescription, dueDate, tags) {
    const task = { id: this.nextId, userId, taskDescription, dueDate, tags: new Set(tags), done: false };
    this.nextId++;
    this.taskById.set(task.id, task);
    if (!this.tasksByUser.has(userId)) {
      this.tasksByUser.set(userId, []);
    }
    const tasks = this.tasksByUser.get(userId);
    tasks.push(task);
    tasks.sort((a, b) => a.dueDate - b.dueDate);
    return task.id;
  }

  getAllTasks(userId) {
    const tasks = this.tasksByUser.get(userId) ?? [];
    return tasks.filter(task => !task.done).map(task => task.taskDescription);
  }

  getTasksForTag(userId, tag) {
    const tasks = this.tasksByUser.get(userId) ?? [];
    return tasks.filter(task => !task.done && task.tags.has(tag)).map(task => task.taskDescription);
  }

  completeTask(userId, taskId) {
    const task = this.taskById.get(taskId);
    if (task && task.userId === userId) {
      task.done = true;
    }
  }
}

