class TodoList {
  constructor() {
    this.all = [];
    this.finished = new Set();
  }
  addTask(userId, taskDescription, dueDate, tags) {
    this.all.push([userId, taskDescription, dueDate, tags.slice()]);
    return this.all.length;
  }
  pending(userId, keep) {
    const rows = [];
    for (let k = 0; k < this.all.length; k++) {
      const [owner, text, due, tags] = this.all[k];
      if (owner === userId && !this.finished.has(k + 1) && keep(tags)) rows.push([due, text]);
    }
    for (let a = 0; a < rows.length; a++)
      for (let b = 0; b + 1 < rows.length - a; b++)
        if (rows[b][0] > rows[b + 1][0]) [rows[b], rows[b + 1]] = [rows[b + 1], rows[b]];
    return rows.map(row => row[1]);
  }
  getAllTasks(userId) {
    return this.pending(userId, () => true);
  }
  getTasksForTag(userId, tag) {
    return this.pending(userId, tags => tags.indexOf(tag) !== -1);
  }
  completeTask(userId, taskId) {
    if (taskId >= 1 && taskId <= this.all.length && this.all[taskId - 1][0] === userId) this.finished.add(taskId);
  }
}

