function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const chars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  const word = (length) => Array.from({ length }, () => pick(chars)).join('');
  const large = size === 'large';
  const users = large ? int(1, 8) : int(1, 3);
  const userIds = Array.from({ length: users }, () => int(1, 100));
  const tagPool = large ? Array.from({ length: int(3, 12) }, () => word(int(1, 20))) : ['P1', 'p1', 'home', 'work'].slice(0, int(1, 4));
  const dueDates = Array.from({ length: 100 }, (_, k) => k + 1);
  for (let k = dueDates.length - 1; k > 0; k--) {
    const j = Math.floor(rand() * (k + 1));
    [dueDates[k], dueDates[j]] = [dueDates[j], dueDates[k]];
  }
  const left = { addTask: 100, getAllTasks: 100, getTasksForTag: 100, completeTask: 100 };
  const calls = large ? 400 : int(1, 16);
  const operations = ['TodoList'];
  const args = [[]];
  const owners = [];
  for (let i = 0; i < calls; i++) {
    const roll = rand();
    let op = roll < 0.35 ? 'addTask' : roll < 0.55 ? 'getAllTasks' : roll < 0.75 ? 'getTasksForTag' : 'completeTask';
    if (left[op] === 0) op = Object.keys(left).find(name => left[name] > 0);
    left[op]--;
    if (op === 'addTask') {
      const userId = pick(userIds);
      const tagCount = rand() < 0.03 ? Math.min(100, tagPool.length) : int(0, Math.min(3, tagPool.length));
      const shuffled = tagPool.slice();
      for (let k = shuffled.length - 1; k > 0; k--) {
        const j = Math.floor(rand() * (k + 1));
        [shuffled[k], shuffled[j]] = [shuffled[j], shuffled[k]];
      }
      const tags = shuffled.slice(0, tagCount);
      const description = large ? word(int(1, 50)) : 'Task' + (owners.length + 1);
      operations.push(op);
      args.push([userId, description, dueDates[owners.length], tags]);
      owners.push(userId);
    } else if (op === 'getAllTasks') {
      operations.push(op);
      args.push([rand() < 0.9 ? pick(userIds) : int(1, 100)]);
    } else if (op === 'getTasksForTag') {
      operations.push(op);
      args.push([pick(userIds), rand() < 0.9 ? pick(tagPool) : 'none']);
    } else {
      const taskId = owners.length && rand() < 0.85 ? int(1, owners.length) : int(1, Math.min(100, owners.length + 3));
      const userId = taskId <= owners.length && rand() < 0.75 ? owners[taskId - 1] : pick(userIds);
      operations.push(op);
      args.push([userId, taskId]);
    }
  }
  return [operations, args];
}
